const std::vector<std::vector<double>> &SKStrideRamachandranMaps::helixProbabilityMap()
{
  return kHelixMap;
}

const std::vector<std::vector<double>> &SKStrideRamachandranMaps::sheetProbabilityMap()
{
  return kSheetMap;
}

double SKStrideRamachandranMaps::probability(const std::vector<std::vector<double>> &map, double phiDegrees, double psiDegrees)
{
  if (!(phiDegrees > minPhiPsiDegrees && phiDegrees <= minPhiPsiDegrees + static_cast<double>(pixelCount) * phiPsiStepDegrees))
  {
    return 0.0;
  }
  if (!(psiDegrees > minPhiPsiDegrees && psiDegrees <= minPhiPsiDegrees + static_cast<double>(pixelCount) * phiPsiStepDegrees))
  {
    return 0.0;
  }
  const int phiIndex = std::min(std::max(static_cast<int>(std::floor((phiDegrees - minPhiPsiDegrees) / phiPsiStepDegrees)), 0), pixelCount - 1);
  const int psiIndex = std::min(std::max(static_cast<int>(std::floor((psiDegrees - minPhiPsiDegrees) / phiPsiStepDegrees)), 0), pixelCount - 1);
  return map[static_cast<size_t>(phiIndex)][static_cast<size_t>(psiIndex)];
}
